#nullable enable
using Modular.Modules.Contracts; namespace Modular.Modules.LicenseManagement.Application;
public sealed class LicenseManagementService { readonly ILicenseCatalog catalog; readonly LicenseManagementValidator validator; public LicenseManagementService(ILicenseCatalog c,LicenseManagementValidator v)=>(catalog,validator)=(c,v); public IReadOnlyCollection<LicenseRecord> List()=>catalog.List();public LicenseRecord? Get(Guid id)=>catalog.Find(id);public ServiceResult<LicenseRecord> Register(LicenseInput x){var v=validator.Validate(x);if(!v.IsValid)return ServiceResult<LicenseRecord>.Invalid(v.Errors);if(catalog.FindByKey(x.Key.Trim()) is not null)return ServiceResult<LicenseRecord>.Invalid(new[]{"License key is already registered."});var l=new LicenseRecord(Guid.NewGuid(),x.Key.Trim(),x.Product.Trim(),x.Customer.Trim(),x.TenantId?.Trim(),x.IssuedUtc,x.ExpiresUtc,LicenseStatus.Pending,Features(x.Features));return ServiceResult<LicenseRecord>.Success(catalog.Upsert(l));}public ServiceResult<LicenseRecord> Activate(Guid id,string? tenant){var old=catalog.Find(id);if(old is null)return ServiceResult<LicenseRecord>.Invalid(new[]{"License was not found."});if(old.ExpiresUtc<=DateTimeOffset.UtcNow)return ServiceResult<LicenseRecord>.Invalid(new[]{"License has expired."});if(string.IsNullOrWhiteSpace(tenant)&&string.IsNullOrWhiteSpace(old.TenantId))return ServiceResult<LicenseRecord>.Invalid(new[]{"A tenant binding is required."});return ServiceResult<LicenseRecord>.Success(catalog.Upsert(old with{TenantId=tenant?.Trim()??old.TenantId,Status=LicenseStatus.Active}));}public ServiceResult<LicenseRecord> AssignFeature(Guid id,string code,bool enabled){var old=catalog.Find(id);if(old is null)return ServiceResult<LicenseRecord>.Invalid(new[]{"License was not found."});if(string.IsNullOrWhiteSpace(code))return ServiceResult<LicenseRecord>.Invalid(new[]{"Feature code is required."});var f=old.Features.ToDictionary(x=>x.Code,StringComparer.OrdinalIgnoreCase);f[code.Trim()]=new(code.Trim(),code.Trim(),enabled);return ServiceResult<LicenseRecord>.Success(catalog.Upsert(old with{Features=f.Values.ToArray()}));}static IReadOnlyCollection<LicenseFeature> Features(IEnumerable<string> x)=>x.Where(y=>!string.IsNullOrWhiteSpace(y)).Select(y=>new LicenseFeature(y.Trim(),y.Trim(),true)).DistinctBy(y=>y.Code,StringComparer.OrdinalIgnoreCase).ToArray();}
public sealed record ServiceResult<T>(T? Value,IReadOnlyCollection<string> Errors){public bool Succeeded=>Errors.Count==0&&Value is not null;public static ServiceResult<T> Success(T x)=>new(x,Array.Empty<string>());public static ServiceResult<T> Invalid(IEnumerable<string> e)=>new(default,e.ToArray());}
